insert into public.institutions (name, acronym, website) values
('Superintendencia Nacional de Aduanas y de Administración Tributaria','SUNAT','https://www.sunat.gob.pe'), ('Instituto Nacional de Defensa de la Competencia y de la Protección de la Propiedad Intelectual','Indecopi','https://www.indecopi.gob.pe'), ('Dirección General de Salud Ambiental e Inocuidad Alimentaria','DIGESA','https://www.digesa.minsa.gob.pe'), ('Municipalidad distrital','Municipalidad','https://www.gob.pe'), ('Autoridad Nacional de Protección de Datos Personales','ANPD','https://www.gob.pe/anpd') on conflict (name) do nothing;
insert into public.business_activities (name, category) values
('Restaurante','Alimentos y bebidas'),('Cafetería','Alimentos y bebidas'),('Pollería','Alimentos y bebidas'),('Cevichería','Alimentos y bebidas'),('Pizzería','Alimentos y bebidas'),('Comida rápida','Alimentos y bebidas'),('Restaurante de menú o comida casera','Alimentos y bebidas'),('Comida para llevar','Alimentos y bebidas'),('Cocina exclusiva para delivery','Alimentos y bebidas'),('Food truck o puesto móvil','Alimentos y bebidas') on conflict (name) do nothing;
insert into public.ciiu_codes (code, description) values ('5610','Actividades de restaurantes y de servicio móvil de comidas') on conflict (code) do nothing;
insert into public.activity_ciiu (activity_id, ciiu_id) select a.id, c.id from public.business_activities a cross join public.ciiu_codes c where a.name in ('Restaurante', 'Cafetería', 'Pollería', 'Cevichería', 'Pizzería', 'Comida rápida', 'Restaurante de menú o comida casera', 'Comida para llevar', 'Cocina exclusiva para delivery', 'Food truck o puesto móvil') and c.code = '5610' on conflict do nothing;
insert into public.sources (slug, institution_id, title, url, reviewed_at) values
('sunat-ruc',(select id from public.institutions where acronym='SUNAT'),'Inscríbete en el RUC','https://centrovirtual.sunat.gob.pe/tramites/inscribete-ruc','2026-10-01'), ('sunat-planilla',(select id from public.institutions where acronym='SUNAT'),'Planilla Electrónica','https://www.gob.pe/8071-planilla-electronica','2026-10-01'), ('licencia',(select id from public.institutions where acronym='Municipalidad'),'Ley Marco de Licencia de Funcionamiento','https://www.gob.pe/institucion/congreso-de-la-republica/normas-legales/1788305-28976','2026-10-01'), ('indecopi',(select id from public.institutions where acronym='Indecopi'),'Libro de Reclamaciones','https://consumidor.gob.pe/libro-de-reclamaciones/','2026-10-01'), ('digesa',(select id from public.institutions where acronym='DIGESA'),'Norma sanitaria para restaurantes y servicios afines','https://www.gob.pe/institucion/minsa/normas-legales/195873-822-2018-minsa','2026-10-01') on conflict (slug) do nothing;
